 wolf:'<path d="M29 70 37 48 35 29 51 42 61 38 79 31 76 47 88 58 81 75 62 88 48 81 40 70Z"/><path d="m37 48 14 8 10-18m-10 18 14 8 11-17M51 56l-3 25m17-17-3 24m-22-18 11-2 11 8 10-6 9 5M66 53l7-3m-22 6-9-4"/><path d="m51 68 11-4 5 7-5 5Z" fill="currentColor" fill-opacity=".3"/>',
 flame:'<path d="M62 27c4 19 24 24 24 43 0 14-11 23-25 23-16 0-27-11-27-25 0-10 7-19 15-24-3 12 0 19 5 23 10-12 15-21 8-40Z"/><path d="M60 59c3 10 14 12 14 22 0 8-7 12-14 12-9 0-14-6-14-13 0-7 5-12 10-15-2 8 0 11 4 13 5-7 5-13 0-19Z" fill="currentColor" fill-opacity=".12"/>',
 lion:'<path d="m60 28 16 5 12 15 3 21-14 19-17 9-17-9-14-19 3-21 12-15Z"/><path d="m43 43 17-7 17 7-3 17 5 11-10 13H51L41 71l5-11Z"/><path d="m43 51 10 5m24-5-10 5m-16 9h18l-9 9Zm9 9v10m-9-5 9 5 9-5M32 48l11 3M29 69l12 2m47-23-11 3m14 18-12 2M43 88l8-4m26 4-8-4"/>',
