 swords:'<path d="m32 29 13 5 37 46-6 5-38-45Zm56 0-13 5-37 46 6 5 38-45Z"/><path d="m69 86 17-14m-8 11 10 12m-5 2 10-8M34 72l17 14m-9-3L32 95m-5-6 10 8"/>',
